CREATE TABLE IF NOT EXISTS guild_cohort_content_clock (
    Id INTEGER NOT NULL PRIMARY KEY CHECK(Id=1),
    Revision INTEGER NOT NULL CHECK(typeof(Revision)='integer' AND Revision>=1)
);

CREATE TABLE IF NOT EXISTS guild_cohort_result_observations (
    QuestId TEXT NOT NULL PRIMARY KEY REFERENCES guild_quests(Id) ON DELETE RESTRICT,
    ResultId TEXT NOT NULL,
    ProofDigest BLOB NOT NULL CHECK(typeof(ProofDigest)='blob' AND length(ProofDigest)=32)
);

CREATE TABLE IF NOT EXISTS guild_cohort_settlement_clock (
    RootAccountId TEXT NOT NULL PRIMARY KEY,
    Revision INTEGER NOT NULL CHECK(typeof(Revision)='integer' AND Revision>=1)
);

CREATE TABLE IF NOT EXISTS guild_event_streams (
    RootQuestId TEXT NOT NULL PRIMARY KEY CHECK(RootQuestId=upper(RootQuestId) AND length(RootQuestId)=36 AND substr(RootQuestId,9,1)='-' AND substr(RootQuestId,14,1)='-' AND substr(RootQuestId,19,1)='-' AND substr(RootQuestId,24,1)='-' AND length(replace(RootQuestId,'-',''))=32 AND replace(RootQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND RootQuestId<>'00000000-0000-0000-0000-000000000000'),
    LastSequence INTEGER NOT NULL CHECK(typeof(LastSequence)='integer' AND LastSequence>=0),
    RetainedAfterSequence INTEGER NOT NULL DEFAULT 0 CHECK(typeof(RetainedAfterSequence)='integer' AND RetainedAfterSequence>=0),
    CHECK(RetainedAfterSequence<=LastSequence)
);

CREATE TABLE IF NOT EXISTS guild_quest_budget (
    QuestId TEXT NOT NULL PRIMARY KEY REFERENCES guild_quests(Id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED CHECK(QuestId=upper(QuestId) AND length(QuestId)=36 AND substr(QuestId,9,1)='-' AND substr(QuestId,14,1)='-' AND substr(QuestId,19,1)='-' AND substr(QuestId,24,1)='-' AND length(replace(QuestId,'-',''))=32 AND replace(QuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestId<>'00000000-0000-0000-0000-000000000000'),
    AccountId TEXT NOT NULL UNIQUE REFERENCES guild_budget_accounts(AccountId) ON DELETE RESTRICT CHECK(AccountId=upper(AccountId) AND length(AccountId)=36 AND substr(AccountId,9,1)='-' AND substr(AccountId,14,1)='-' AND substr(AccountId,19,1)='-' AND substr(AccountId,24,1)='-' AND length(replace(AccountId,'-',''))=32 AND replace(AccountId,'-','') NOT GLOB '*[^0-9A-F]*' AND AccountId<>'00000000-0000-0000-0000-000000000000')
);

CREATE TABLE IF NOT EXISTS guild_quest_start_intents (
    QuestId TEXT NOT NULL PRIMARY KEY REFERENCES guild_quests(Id) ON DELETE RESTRICT CHECK(QuestId=upper(QuestId) AND length(QuestId)=36 AND substr(QuestId,9,1)='-' AND substr(QuestId,14,1)='-' AND substr(QuestId,19,1)='-' AND substr(QuestId,24,1)='-' AND length(replace(QuestId,'-',''))=32 AND replace(QuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestId<>'00000000-0000-0000-0000-000000000000'),
    CreatedAtUtc TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS guild_signet_authority_state (
    StateKey INTEGER NOT NULL PRIMARY KEY CHECK(StateKey=1),
    Epoch TEXT NOT NULL CHECK(length(Epoch)=36)
);

CREATE TABLE IF NOT EXISTS guild_workspace_authority_state (
    StateKey INTEGER NOT NULL PRIMARY KEY CHECK(StateKey=1),
    InstallationGeneration TEXT NOT NULL CHECK(typeof(InstallationGeneration)='text' AND InstallationGeneration=upper(InstallationGeneration) AND length(InstallationGeneration)=36 AND substr(InstallationGeneration,9,1)='-' AND substr(InstallationGeneration,14,1)='-' AND substr(InstallationGeneration,19,1)='-' AND substr(InstallationGeneration,24,1)='-' AND length(replace(InstallationGeneration,'-',''))=32 AND replace(InstallationGeneration,'-','') NOT GLOB '*[^0-9A-F]*' AND InstallationGeneration<>'00000000-0000-0000-0000-000000000000'),
    NativeOperatorPrincipalId TEXT NOT NULL CHECK(typeof(NativeOperatorPrincipalId)='text' AND NativeOperatorPrincipalId=upper(NativeOperatorPrincipalId) AND length(NativeOperatorPrincipalId)=36 AND substr(NativeOperatorPrincipalId,9,1)='-' AND substr(NativeOperatorPrincipalId,14,1)='-' AND substr(NativeOperatorPrincipalId,19,1)='-' AND substr(NativeOperatorPrincipalId,24,1)='-' AND length(replace(NativeOperatorPrincipalId,'-',''))=32 AND replace(NativeOperatorPrincipalId,'-','') NOT GLOB '*[^0-9A-F]*' AND NativeOperatorPrincipalId<>'00000000-0000-0000-0000-000000000000')
);

